import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"What is google-search-console-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788283422000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-google-search-console-mcp" tabindex="-1">What is google-search-console-mcp? <a class="header-anchor" href="#what-is-google-search-console-mcp" aria-label="Permalink to “What is google-search-console-mcp?”">​</a></h1><p>An MCP server for <a href="https://search.google.com/search-console/about" target="_blank" rel="noreferrer">Google Search Console</a>, the service that tells you how Google sees your site — which queries brought people to it, which pages are indexed, and what it made of your sitemaps.</p><p>It covers three Google APIs, because Search Console alone is not enough to set a property up: <a href="https://developers.google.com/webmaster-tools/v1/api_reference_index" target="_blank" rel="noreferrer">Search Console v1</a> for properties, sitemaps, analytics and URL inspection, <a href="https://developers.google.com/site-verification/v1" target="_blank" rel="noreferrer">Site Verification v1</a> for proving ownership, and the <a href="https://developers.google.com/search/apis/indexing-api/v3/quickstart" target="_blank" rel="noreferrer">Indexing API v3</a> for change notifications.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Search Console&#39;s web interface is fine for looking. It is a poor place to <em>do</em> anything repetitive: adding a property means clicking through a verification wizard, submitting forty sitemaps means submitting them forty times, and answering &quot;which of these two hundred pages is not indexed&quot; means inspecting them one at a time.</p><p>Those are exactly the jobs an MCP client is good at — and the ones where getting the details wrong is easy and invisible. A property spelled <code>https://example.com</code> instead of <code>https://example.com/</code> is a different property that answers 403. A seven-day range computed in UTC covers six days of data. A totals row averaged across query CTRs is off by an order of magnitude. This server gets those right so the conversation above it does not have to.</p><h2 id="what-it-will-not-do" tabindex="-1">What it will not do <a class="header-anchor" href="#what-it-will-not-do" aria-label="Permalink to “What it will not do”">​</a></h2><ul><li><strong>Make Google crawl something.</strong> Nothing can. <code>request_indexing</code> exists because the API does, and it only has an effect on JobPosting and BroadcastEvent pages; every description involving it says so.</li><li><strong>Report live page state.</strong> <code>inspect_url</code> returns what Google last indexed, not a fresh fetch. A page fixed an hour ago still shows the old verdict.</li><li><strong>Place a verification token for you.</strong> Creating a DNS record or editing a template is a human step by design. <code>setup_site</code> gets you the exact record to paste and picks up again afterwards.</li><li><strong>Show you today&#39;s numbers.</strong> Search Console finalises data two to three days behind. <code>dataState: &quot;ALL&quot;</code> includes the incomplete recent days; nothing includes the missing ones.</li></ul><h2 id="what-it-is-careful-about" tabindex="-1">What it is careful about <a class="header-anchor" href="#what-it-is-careful-about" aria-label="Permalink to “What it is careful about”">​</a></h2><p>Four operations cannot be undone and <a href="/guide/approval">ask a person</a> before they act: removing a property (which discards roughly sixteen months of history Google will not give back), removing a sitemap, giving up ownership, and replacing the owner list — the last one because the list you pass is the complete list afterwards, so it removes everyone else. Where the client cannot show a dialog, they fall back to a token that only ever appears in a previous tool result.</p><p>Everything the APIs return is marked as untrusted content. Search queries are strings the public typed into Google; page titles and crawl diagnostics come from whoever runs the crawled site.</p><p>And the OAuth scopes follow the tools: narrowing the tool list narrows what the credential is used for. See <a href="/guide/security">Security</a>.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};